# generated by tools/ail2py.py from csv_rewrite_stream_main.ail; edit the .ail until onelang s16
from csv_rewrite_stream import *
from file_identity import *
from ail import open_binary
import sys

# Streaming profile: after validation/open, later errors may truncate output or
# leave a prefix. Unlike csv_rewrite, this does not validate the whole input first.
def main() -> int:
    if len(sys.argv) != 5:
        print('usage: csv_rewrite_stream INPUT OUTPUT CHUNK MAX_ROW_UNITS', file=sys.stderr)
        return 2
    try:
        input: str = sys.argv[1]
        output: str = sys.argv[2]
        size: int = parse_int64_text(sys.argv[3])
        cap: int = parse_int64_text(sys.argv[4])
        if size <= 0 or size > 1048576 or cap <= 0 or (cap > 1048576):
            raise ValueError
        if input == output or file_paths_same(input, output):
            raise ValueError
        reader = open_binary(input, 'rb')
        try:
            writer = open_binary(output, 'wb')
            try:
                csv_rewrite_stream(reader, writer, size, cap)
                writer.flush()
                return 0
            finally:
                writer.close()
        finally:
            reader.close()
    except UnicodeDecodeError:
        print('invalid UTF-8 CSV input', file=sys.stderr)
        return 4
    except ValueError:
        print('invalid CSV input, row limit, argument or output alias', file=sys.stderr)
        return 4
    except OSError:
        print('CSV rewrite file error', file=sys.stderr)
        return 3
    return 0

if __name__ == "__main__":
    sys.exit(main())
